import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, getLastDayOfMonth } from './dates.js';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './totals.js';

export { lineTotal, lineDiscount, lineVat, invoiceTotals };

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} options
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);

  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = getLastDayOfMonth(issueDate);
  } else {
    return fail('TERMS_INVALID');
  }

  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    let discountPercent;
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier] ?? 0;
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} options
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  let lineDiscountPercent;
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
    lineDiscountPercent = discountPercent;
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (customerResult.ok) {
      lineDiscountPercent = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;
    } else {
      lineDiscountPercent = 0;
    }
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLine = newLines.find((line) => line.sku === sku);

  if (existingLine) {
    existingLine.qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: lineDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to issued.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of existing invoice numbers already in use
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    number,
    lines: invoice.lines.map((line) => ({ ...line })),
    terms: invoice.terms,
    dueDate: invoice.dueDate,
  });
}

/**
 * Apply a voucher to an invoice.
 * @param {{ status: string, voucher?: object, lines: Array }} invoice
 * @param {{ code: string, amount: number }} options
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  const newInvoice = {
    ...invoice,
    voucher: { code, amount },
  };

  return ok(newInvoice);
}

