});

test('bulkDiscount returns 0 for qty = 0', () => {
  const line = { qty: 0, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 0);
});

test('bulkDiscount applies 2.5% to qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 250);
});

test('bulkDiscount applies after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const base = 10000;
  const lineDisc = 1000;
  const afterLineDisc = base - lineDisc;
  const bulk = Math.round(afterLineDisc * 2.5 / 100);
  assert.equal(bulkDiscount(line), bulk);
});

test('bulkDiscount with larger amount', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 0 };
  const base = 95000;
  const bulk = Math.round(base * 2.5 / 100);
  assert.equal(bulkDiscount(line), bulk);
});

test('bulkDiscount with qty = 10 boundary', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
