});

test('invoiceTotals calculates VAT after bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const base = 10000;
  const bulkDisc = 250;
  const afterAllDiscounts = base - bulkDisc;
  const expectedVat = Math.round(afterAllDiscounts * 21 / 100);

  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
});

test('invoiceTotals with bulk discount and line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const base = 10000;
  const lineDisc = 1000;
  const afterLineDisc = base - lineDisc;
  const bulkDisc = Math.round(afterLineDisc * 2.5 / 100);
  const afterAllDiscounts = afterLineDisc - bulkDisc;
  const expectedVat = Math.round(afterAllDiscounts * 21 / 100);
  const expectedTotal = base - lineDisc - bulkDisc + expectedVat;

  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, lineDisc + bulkDisc);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

