  assert.ok(totals.hasOwnProperty('vat'));
  assert.ok(totals.hasOwnProperty('voucher'));
  assert.ok(totals.hasOwnProperty('total'));
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with complex scenario', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
      { qty: 20, unitPrice: 1000, discountPercent: 2.5, vatRate: 9 },
      { qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 },
    ],
    voucher: { code: 'PROMO', amount: 5000 },
  };

  const totals = invoiceTotals(invoice);

  assert.ok(totals.subtotal > 0);
  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.equal(totals.voucher, 5000);
  assert.ok(totals.total > 0);
});

test('bulkDiscount returns 0 for qty < 10', () => {
  const line = { qty: 9, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 0);
});

test('bulkDiscount returns 0 for qty = 0', () => {
  const line = { qty: 0, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 0);
});

test('bulkDiscount applies 2.5% to qty >= 10', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 250);
});

test('bulkDiscount applies after line discount', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10 };
  const base = 10000;
  const lineDisc = 1000;
  const afterLineDisc = base - lineDisc;
  const bulk = Math.round(afterLineDisc * 2.5 / 100);
  assert.equal(bulkDiscount(line), bulk);
});

test('bulkDiscount with larger amount', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 0 };
  const base = 95000;
  const bulk = Math.round(base * 2.5 / 100);
  assert.equal(bulkDiscount(line), bulk);
});

test('bulkDiscount with qty = 10 boundary', () => {
  const line = { qty: 10, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 250);
});

test('bulkDiscount with qty = 11', () => {
  const line = { qty: 11, unitPrice: 1000, discountPercent: 0 };
  assert.equal(bulkDiscount(line), 275);
});

test('invoiceTotals includes bulk discount in total discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const expectedDiscount = 250;

  assert.equal(totals.discount, expectedDiscount);
});

test('invoiceTotals calculates VAT after bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const base = 10000;
  const bulkDisc = 250;
  const afterAllDiscounts = base - bulkDisc;
  const expectedVat = Math.round(afterAllDiscounts * 21 / 100);

  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250);
});

test('invoiceTotals with bulk discount and line discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const base = 10000;
  const lineDisc = 1000;
  const afterLineDisc = base - lineDisc;
  const bulkDisc = Math.round(afterLineDisc * 2.5 / 100);
  const afterAllDiscounts = afterLineDisc - bulkDisc;
  const expectedVat = Math.round(afterAllDiscounts * 21 / 100);
  const expectedTotal = base - lineDisc - bulkDisc + expectedVat;

  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, lineDisc + bulkDisc);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with multiple lines and bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);

  const line1Total = 10000;
  const line1Bulk = 250;
  const line1AfterDiscount = line1Total - line1Bulk;
  const line1Vat = Math.round(line1AfterDiscount * 21 / 100);

  const line2Total = 5000;
  const line2Bulk = 0;
  const line2AfterDiscount = line2Total - line2Bulk;
  const line2Vat = Math.round(line2AfterDiscount * 21 / 100);

  const expectedDiscount = line1Bulk + line2Bulk;
  const expectedVat = line1Vat + line2Vat;

  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with bulk discount and voucher', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
    ],
    voucher: { code: 'BULK', amount: 1000 },
