file.content:
import { roundCents } from './money.js';

/**
 * Calculate the total price (in cents) for a single line item.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount (in cents) for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return roundCents(total * discountPercent / 100);
}

/**
 * Calculate the bulk discount (in cents) for a single line item (2.5% for 10+ units, applied after line discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function bulkDiscount(line) {
  if (line.qty < 10) {
    return 0;
  }
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const afterFirstDiscount = total - discount;
  return roundCents(afterFirstDiscount * 2.5 / 100);
}

/**
 * Calculate the VAT (in cents) for a single line item, applied after discount.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const afterDiscount = total - discount;
  const vatRate = line.vatRate ?? 0;
  return roundCents(afterDiscount * vatRate / 100);
}

/**
 * Calculate the totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line) + bulkDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => {
    const total = lineTotal(line);
    const lineDisc = lineDiscount(line);
    const bulk = bulkDiscount(line);
    const afterAllDiscounts = total - lineDisc - bulk;
    const vatRate = line.vatRate ?? 0;
    return sum + roundCents(afterAllDiscounts * vatRate / 100);
  }, 0);
  const voucher = invoice.voucher ? invoice.voucher.amount : 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}
